public class Caverphone_caverphone_TriageGen1Test {

    private Caverphone caverphone;

    @Before
    public void setUp() {
        caverphone = new Caverphone();
    }











    @Test
    public void testCaverphone_VowelsAndJ() {
        // [aeiou] at start -> A
        // [aeiou] elsewhere -> 3
        // j -> y (2.0)
        // y (2.0) logic
        assertNotNull(caverphone.caverphone("apple"));
        assertNotNull(caverphone.caverphone("egg"));
        assertNotNull(caverphone.caverphone("ink"));
        assertNotNull(caverphone.caverphone("orange"));
        assertNotNull(caverphone.caverphone("under"));
        assertNotNull(caverphone.caverphone("jump"));
    }








}

